     1→import { useCallback } from 'react';
     2→import { usePlaybookStore } from '../store/playbookStore';
     3→import { usePlayerStore } from '../store/playerStore';
     4→import { useCameraStore } from '../store/cameraStore';
     5→import { useAnnotationStore } from '../store/annotationStore';
     6→
     7→export function usePlaybook() {
     8→  const { savePlaybook, loadPlaybook: loadPlaybookFromStore } = usePlaybookStore();
     9→  const players = usePlayerStore((state) => state.players);
    10→  const { position, target, zoom } = useCameraStore();
    11→  const annotations = useAnnotationStore((state) => state.annotations);
    12→  
    13→  const saveCurrentScenario = useCallback(async (name: string, description?: string) => {
    14→    try {
    15→      const id = await savePlaybook({
    16→        name,
    17→        description,
    18→        playerPositions: players,
    19→        cameraPosition: position,
    20→        cameraTarget: target,
    21→        cameraZoom: zoom,
    22→        annotations: annotations,
    23→      });
    24→      return id;
    25→    } catch (error) {
    26→      console.error('Error saving scenario:', error);
    27→      throw error;
    28→    }
    29→  }, [savePlaybook, players, position, target, zoom, annotations]);
    30→  
    31→  const loadScenario = useCallback(async (playbookId: number) => {
    32→    try {
    33→      const playbook = await loadPlaybookFromStore(playbookId);
    34→      if (playbook) {
    35→        // Restore player positions
    36→        usePlayerStore.setState({ players: playbook.playerPositions });
    37→        
    38→        // Restore camera
    39→        useCameraStore.setState({
    40→          position: playbook.cameraPosition,
    41→          target: playbook.cameraTarget,
    42→          zoom: playbook.cameraZoom,
    43→        });
    44→        
    45→        // Restore annotations
    46→        if (playbook.annotations) {
    47→          useAnnotationStore.setState({ annotations: playbook.annotations });
    48→        }
    49→      }
    50→    } catch (error) {
    51→      console.error('Error loading scenario:', error);
    52→      throw error;
    53→    }
    54→  }, [loadPlaybookFromStore]);
    55→  
    56→  return {
    57→    saveCurrentScenario,
    58→    loadScenario,
    59→  };
    60→}
