     1→import { useRef, useState } from 'react';
     2→import { useFrame, useThree } from '@react-three/fiber';
     3→import { Text } from '@react-three/drei';
     4→import { Mesh, Vector3, Plane } from 'three';
     5→import { Player } from '../../models/PlayerModel';
     6→import { usePlayerStore } from '../../store/playerStore';
     7→import { snapToField } from '../../utils/fieldGeometry';
     8→
     9→interface PlayerProps {
    10→  player: Player;
    11→}
    12→
    13→export function PlayerComponent({ player }: PlayerProps) {
    14→  const meshRef = useRef<Mesh>(null);
    15→  const groupRef = useRef<any>(null);
    16→  const [hovered, setHovered] = useState(false);
    17→  const [isDragging, setIsDragging] = useState(false);
    18→  const { selectedPlayerId, selectPlayer, updatePlayerPosition, showPlayerNames, startEditingPlayerName } = usePlayerStore();
    19→  const { camera, raycaster } = useThree();
    20→  const isSelected = selectedPlayerId === player.id;
    21→  
    22→  useFrame((state) => {
    23→    if (meshRef.current) {
    24→      meshRef.current.rotation.y = player.rotation;
    25→    }
    26→    
    27→    // Handle dragging with global pointer events
    28→    if (isDragging) {
    29→      raycaster.setFromCamera(state.pointer, camera);
    30→      const planeNormal = new Vector3(0, 1, 0);
    31→      const planePoint = new Vector3(0, 0, 0);
    32→      const intersection = raycaster.ray.intersectPlane(
    33→        new Plane(planeNormal, -planeNormal.dot(planePoint)),
    34→        new Vector3()
    35→      );
    36→      
    37→      if (intersection) {
    38→        const [x, z] = snapToField(intersection.x, intersection.z);
    39→        updatePlayerPosition(player.id, [x, 0, z]);
    40→      }
    41→    }
    42→  });
    43→  
    44→  const handleClick = (e: any) => {
    45→    e.stopPropagation();
    46→    if (isSelected) {
    47→      // Click on already-selected player opens name edit
    48→      startEditingPlayerName(player.id);
    49→    } else {
    50→      selectPlayer(player.id);
    51→    }
    52→  };
    53→  
    54→  const handlePointerDown = (e: any) => {
    55→    e.stopPropagation();
    56→    selectPlayer(player.id);
    57→    setIsDragging(true);
    58→  };
    59→  
    60→  const handlePointerMove = (e: any) => {
    61→    // Movement is handled in useFrame for smoother dragging
    62→    if (isDragging) {
    63→      e.stopPropagation();
    64→    }
    65→  };
    66→  
    67→  const handlePointerUp = (e: any) => {
    68→    e.stopPropagation();
    69→    setIsDragging(false);
    70→  };
    71→  
    72→  return (
    73→    <group
    74→      ref={groupRef}
    75→      position={player.position}
    76→      onClick={handleClick}
    77→      onPointerDown={handlePointerDown}
    78→      onPointerMove={handlePointerMove}
    79→      onPointerUp={handlePointerUp}
    80→      onPointerOver={() => setHovered(true)}
    81→      onPointerOut={() => {
    82→        setHovered(false);
    83→        setIsDragging(false);
    84→      }}
    85→    >
    86→      {/* Player body - capsule shape */}
    87→      <mesh ref={meshRef} castShadow position={[0, 0.9, 0]}>
    88→        <capsuleGeometry args={[0.3, 1.2, 4, 8]} />
    89→        <meshStandardMaterial
    90→          color={isSelected ? '#ffff00' : hovered ? '#ffffff' : player.color}
    91→          emissive={isSelected ? '#ffff00' : player.color}
    92→          emissiveIntensity={isSelected ? 0.3 : 0.1}
    93→        />
    94→      </mesh>
    95→      
    96→      {/* Player number label */}
    97→      {player.number && (
    98→        <mesh position={[0, 1.5, 0.35]} rotation={[0, 0, 0]}>
    99→          <planeGeometry args={[0.4, 0.4]} />
   100→          <meshStandardMaterial color="#ffffff" />
   101→        </mesh>
   102→      )}
   103→
   104→      {/* Player name label */}
   105→      {showPlayerNames && player.playerName && (
   106→        <Text
   107→          position={[0, 2.1, 0]}
   108→          fontSize={0.4}
   109→          color="#ffffff"
   110→          anchorX="center"
   111→          anchorY="middle"
   112→          outlineWidth={0.05}
   113→          outlineColor="#000000"
   114→        >
   115→          {player.playerName}
   116→        </Text>
   117→      )}
   118→
   119→      {/* Selection indicator ring */}
